python3 - <<'PY'
import xml.etree.ElementTree as ET
p='/conf/config.xml'
root=ET.parse(p).getroot()
print('root', root.tag)
for c in root:
    print('top', c.tag)
for parent_path in ['interfaces','filter','nat','system','dhcpd','unbound','dnsmasq','gateways','staticroutes']:
    e=root.find(parent_path)
    print('\n###', parent_path, 'present=', e is not None)
    if e is not None:
        def rec(x, depth=0):
            if depth>5: return
            txt=(x.text or '').strip()
            if x.tag in ('password','prv','crt','authorizedkeys','apikeys','secret','key','privatekey'):
                txt='[REDACTED]'
            print('  '*depth + x.tag + (('=' + txt) if txt and len(txt)<180 and not list(x) else ''))
            for y in x: rec(y, depth+1)
        rec(e)
PY

